// What every kind's files share: a generated file, its mark, a role's brief with Every role in it, and the
// rules as AGENTS.md (read by every Copilot surface) with CLAUDE.md only bringing it in.
import type { Role, Spec } from "../spec.ts";

export type Generated = { readonly path: string; readonly text: string };

export const mark = (source: string): string =>
  `<!-- generated by the kit from ${source}; do not edit: change the source and run make agents -->`;

// the role's brief and the project's Every role, so that an agent given no repository instructions has them
export const brief = (role: Role, everyRole: string): string =>
  `${mark(`agents/roles/${role.front.name}.md and agents/rules.md`)}\n\n${role.body}\n\n## Every role (agents/rules.md)\n\n${everyRole}\n`;

// YAML front matter from ordered pairs; every string a JSON string, which YAML reads as written
export const frontMatter = (
  pairs: readonly (readonly [string, string | boolean | readonly string[]])[],
): string =>
  `---\n${pairs
    .map(([k, v]) => `${k}: ${typeof v === "boolean" ? String(v) : JSON.stringify(v)}`)
    .join("\n")}\n---\n`;

export const rulesFiles = (spec: Spec): readonly Generated[] => [
  { path: "AGENTS.md", text: `${mark("agents/rules.md")}\n\n${spec.rules}\n` },
  { path: "CLAUDE.md", text: `${mark("agents/rules.md")}\n\n@AGENTS.md\n` },
];
